def diagnose_pool_hang(cpu_pct: float, common_pool_waiting: int, common_pool_size: int, queued: int) -> str:
    if cpu_pct < 15.0 and common_pool_waiting == common_pool_size and queued > 0:
        return 'COMMONPOOL_SELF_DEADLOCK_OR_IO_STARVATION'
    return 'INVESTIGATE_OTHER_BOTTLENECK'

