def littles_law_threads(qps: float, avg_io_ms: float, safety_factor: float = 1.5) -> int:
    if qps <= 0 or avg_io_ms <= 0:
        raise ValueError('QPS and latency must be positive')
    concurrent = qps * (avg_io_ms / 1000.0)
    return max(4, int(concurrent * safety_factor))

// Safe Virtual Thread pattern with Semaphore backpressure
Semaphore dbPermits = new Semaphore(100);
CompletableFuture.supplyAsync(() -> {
    dbPermits.acquireUninterruptibly();
    try { return queryDatabase(); } finally { dbPermits.release(); }
}, virtualThreadExecutor);

def check_executor_saturation(active: int, max_threads: int, queue_used: int, queue_cap: int) -> str:
    if queue_cap <= 0 or max_threads <= 0:
        raise ValueError('Pool capacities must be positive')
    if (queue_used / queue_cap) > 0.80:
        return 'WARN_IO_QUEUE_BACKPRESSURE'
    return 'OK'
